(function(){'use strict';
function uuid(){
 if(!window.crypto||!window.crypto.getRandomValues)throw new Error('Please open this page using HTTPS in an up-to-date browser.');
 if(typeof window.crypto.randomUUID==='function')return window.crypto.randomUUID();
 const bytes=window.crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;
 return Array.from(bytes,(v,i)=>([4,6,8,10].includes(i)?'-':'')+v.toString(16).padStart(2,'0')).join('');
}

const C=window.CAGE_ADMISSIONS_COMMON,esc=C.esc,root=document.getElementById('ad-public-root'),config=window.CAGE_CONFIG||{},endpoint=(config.supabaseUrl||'').replace(/\/$/,'')+'/functions/v1/academy-admissions';let catalog=[],current=null,access=null,pending=null,paymentId=null,correctionFields=[];
const input=(f,v='')=>`<label class="cage-academy-field ${f.type==='textarea'?'cage-academy-wide':''}"><span>${esc(f.label)}${f.required?' *':''}</span>${f.type==='select'?`<select name="${f.id}" ${f.required?'required':''}><option value="">Choose…</option>${f.options.map(x=>`<option value="${esc(x)}" ${v===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea name="${f.id}" maxlength="5000" ${f.required?'required':''}>${esc(v)}</textarea>`:f.type==='checkbox'?`<input name="${f.id}" type="checkbox" ${v===true?'checked':''} ${f.required?'required':''}>`:`<input name="${f.id}" type="${f.type}" value="${esc(v)}" maxlength="5000" ${f.required?'required':''}>`}</label>`;
async function request(action,form,token){let last;for(let attempt=0;attempt<2;attempt++){const controller=globalThis.AbortController?new AbortController():null,timer=controller?setTimeout(()=>controller.abort(),20000):null;try{const r=await fetch(endpoint+'?action='+encodeURIComponent(action),{method:form?'POST':'GET',headers:{apikey:config.supabaseAnonKey||'',...(token?{'x-application-access':token}:{})},body:form,cache:'no-store',signal:controller?.signal});const text=await r.text();let data={};try{data=text?JSON.parse(text):{};}catch{throw new Error('The application service returned an unreadable response. Please reload and try again.');}if(!r.ok)throw new Error(data.error||`Application service error (${r.status})`);return data;}catch(e){last=e;if(attempt===0&&(e?.name==='AbortError'||/fetch|network|load failed|connection/i.test(String(e?.message||e))))continue;throw e;}finally{if(timer)clearTimeout(timer);}}throw last||new Error('The application service is unavailable.');}
function error(e){let p=document.getElementById('cage-academy-error');if(!p){p=document.createElement('p');p.id='cage-academy-error';p.className='cage-academy-error';p.setAttribute('role','alert');root.prepend(p);}p.textContent=e.message||e;}
function catalogView(){access=null;history.replaceState(null,'',location.pathname);root.innerHTML=`<section class="academy-hero"><p class="cage-academy-eyebrow">Learn. Practise. Progress.</p><h1>Find your next course</h1><p>Choose a programme and an open application call. You can return after applying to upload your proof of payment.</p></section><div class="cage-academy-course-grid">${C.categories.map(category=>`<section class="academy-card"><span class="cage-academy-eyebrow">${esc(category)}</span><h2>${esc(category)}</h2>${catalog.filter(c=>c.category===category).map(c=>`<article class="cage-academy-call"><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><p>${c.start_date?'Starts '+esc(c.start_date):'Dates to be confirmed'} · ${esc(c.currency)} ${Number(c.fee).toLocaleString()}</p><button data-apply-call="${c.id}">${isOpen(c)?'View schedule & apply':'View call'}</button></article>`).join('')||'<p class="cage-academy-muted">No published call yet. Please check again soon.</p>'}</section>`).join('')}</div>`;}
const isOpen=c=>c.accepting&&(!c.closes_on||c.closes_on>=new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Blantyre'}));
function showCall(id){current=catalog.find(c=>c.id===id);if(!current)return;const c=current;history.replaceState(null,'',location.pathname+'?call='+encodeURIComponent(id));let draft={};try{draft=JSON.parse(sessionStorage.getItem('cage-application-draft:'+id)||'{}');}catch{}
 root.innerHTML=`<button class="cage-academy-back" data-catalog>← All courses</button><section class="academy-hero"><p class="cage-academy-eyebrow">${esc(c.category)}</p><h1>${esc(c.title)}</h1><p>${esc(c.description)}</p><p>${esc(c.currency)} ${Number(c.fee).toLocaleString()} · ${esc(c.venue||'Venue to be confirmed')}${c.closes_on?' · Apply by '+esc(c.closes_on):''}</p></section>${isOpen(c)?`<form id="application-form" class="academy-card"><h2 tabindex="-1" id="application-heading">Application details</h2><button type="button" data-jump-timetable>View timetable ↓</button><p class="cage-academy-muted">* Required. ${c.category==='STEM'?'A parent or guardian should complete this form.':'Use your full name as shown on your identity document.'}</p><div class="cage-academy-form-grid">${c.fields.map(f=>input(f,draft[f.id]??'')).join('')}</div><fieldset><legend>Identity document ${c.category==='STEM'?'(optional)':'*'}</legend><p>Upload a National ID, passport or license as PDF, JPG, PNG or WebP. Maximum 10 MB.</p><label class="cage-academy-field"><span>Document type</span><select name="identity_type" ${c.category==='STEM'?'':'required'}><option value="">Choose…</option><option>National ID</option><option>Passport</option><option>License</option></select></label><label class="cage-academy-field"><span>Document file</span><input type="file" name="identity" accept="application/pdf,image/jpeg,image/png,image/webp" ${c.category==='STEM'?'':'required'}></label><p class="cage-academy-muted">Only authorised CAGE application reviewers can access this document.</p></fieldset><label class="cage-academy-trap" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><p id="cage-academy-error" class="cage-academy-error" role="alert"></p><button type="submit">Submit application</button><p class="cage-academy-muted">You will receive a private return link for payment proof. Submitting proof does not automatically confirm payment or enrolment.</p></form>`:'<div class="academy-card">Applications for this call are closed.</div>'}<details class="academy-card" id="course-timetable" open><summary>Course timetable</summary>${c.schedule?.length?C.scheduleHTML(c):'<p>Training dates will be confirmed by CAGE.</p>'}${isOpen(c)?'<button type="button" data-jump-application>↑ Back to application</button>':''}<button type="button" data-print-schedule>Print / save schedule PDF</button></details>`;
}
function returnForm(){root.innerHTML='<section class="academy-card cage-academy-narrow"><h1>Return to your application</h1><p>Use the reference and private access key from your saved application receipt.</p><form id="return-form"><label class="cage-academy-field"><span>Application reference</span><input name="reference" required></label><label class="cage-academy-field"><span>Private access key</span><input name="key" type="password" autocomplete="off" required></label><p id="cage-academy-error" role="alert" class="cage-academy-error"></p><button>Open application</button></form></section>';}
function privateLink(){return location.origin+location.pathname+'#application='+access.id+'&key='+access.key;}
function correctionHTML(data){if(!data.correction){correctionFields=[];return '';}correctionFields=data.correction.fields;return `<section class="academy-card"><h2>Corrections requested</h2><p class="cage-academy-preline">${esc(data.correction.note)}</p><form id="correction-form" data-request="${uuid()}"><div class="cage-academy-form-grid">${correctionFields.map(f=>input(f,data.correction.answers[f.id]??'')).join('')}</div><fieldset><legend>Replace identity document, if requested</legend><label class="cage-academy-field"><span>Document type</span><select name="identity_type"><option value="">Choose…</option><option>National ID</option><option>Passport</option><option>License</option></select></label><label class="cage-academy-field"><span>Replacement PDF or image, maximum 10 MB</span><input name="identity" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"></label><p>Leave the file empty to keep your existing document.</p></fieldset><button type="submit">Send corrected application for review</button></form></section>`;}
async function statusView(){const f=new FormData();f.set('application',access.id);const data=await request('status',f,access.key);history.replaceState(null,'',privateLink());root.innerHTML=`<section class="academy-hero"><p class="cage-academy-eyebrow">${esc(data.intake.category)} · ${esc(data.status)}</p><h1>Your application</h1><p>${esc(data.intake.title)}</p><p>Reference: <strong>${esc(data.id)}</strong></p><button type="button" id="save-receipt">Save private application receipt</button><p class="cage-academy-muted">Keep the receipt or bookmark this private link. It gives access to payment uploads. Do not share it publicly.</p></section>${correctionHTML(data)}<section class="academy-card"><h2>Payment and proof</h2><div class="cage-academy-balance-summary"><strong>Remaining balance: ${esc(data.currency)} ${Number(data.balance?.balance??data.fee).toLocaleString()}</strong><p>Verified payments: ${esc(data.currency)} ${Number(data.balance?.verified_paid||0).toLocaleString()}</p><p>${data.balance?.due_on?'Agreed balance date: '+esc(data.balance.due_on):'No balance payment date recorded.'}</p></div>${Number(data.balance?.balance)>0&&data.status!=='Enrolled'?`<form id="balance-date-form"><label class="cage-academy-field"><span>When will you finish paying the balance?</span><input name="balance_due_on" type="date" value="${esc(data.balance?.due_on||'')}" min="${new Date(Date.now()+7200000).toISOString().slice(0,10)}" required></label><button type="submit">Save proposed payment date</button><p>CAGE will confirm this date when enrolling you. Payment reminders are sent before and on your agreed date while a balance remains.</p></form>`:''}<p>Course fee: ${esc(data.currency)} ${Number(data.fee).toLocaleString()}</p><p class="cage-academy-preline">${esc(data.intake.payment_instructions||'Contact CAGE for payment instructions before paying.')}</p><p>After making payment, upload the confirmation below. Staff will review it; an upload alone does not mark you as paid.</p><form id="payment-proof-form"><div class="cage-academy-form-grid"><label class="cage-academy-field"><span>Amount paid (${esc(data.currency)}) *</span><input name="amount" type="number" min="0.01" step="0.01" required></label><label class="cage-academy-field"><span>Payment date *</span><input name="payment_date" type="date" required></label><label class="cage-academy-field"><span>Transaction reference *</span><input name="payment_reference" maxlength="200" required></label><label class="cage-academy-field"><span>Proof of payment (PDF or image, max 10 MB) *</span><input name="proof" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" required></label></div><p id="cage-academy-error" role="alert" class="cage-academy-error"></p><button>Upload payment proof</button></form><h3>Uploaded evidence</h3>${data.files.map(f=>`<article class="cage-academy-evidence"><strong>${esc(f.kind==='identity'?'Identity document':f.file_name)}</strong><span>${esc(f.review_status)}</span>${f.kind==='payment'?`<small>${esc(data.currency)} ${Number(f.amount).toLocaleString()} · ${esc(f.payment_date)} · ${esc(f.payment_reference)}</small><p>${esc(f.review_note)}</p>`:''}</article>`).join('')||'<p>No files received yet.</p>'}</section>${data.intake.schedule?.length?`<details class="academy-card"><summary>Current course timetable</summary>${C.scheduleHTML(data.intake)}<button type="button" data-print-schedule>Print / save schedule PDF</button></details>`:''}`;current=data.intake;}
function printSchedule(){document.body.classList.add('cage-academy-printing');window.print();document.body.classList.remove('cage-academy-printing');}
document.getElementById('return-application').onclick=returnForm;
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-jump-timetable')){const t=document.getElementById('course-timetable');t.open=true;t.scrollIntoView({behavior:'smooth'});t.querySelector('summary').focus();}if(b.hasAttribute('data-jump-application')){document.getElementById('application-heading')?.focus();document.getElementById('application-form')?.scrollIntoView({behavior:'smooth'});}if(b.dataset.applyCall)showCall(b.dataset.applyCall);if(b.hasAttribute('data-catalog'))catalogView();if(b.hasAttribute('data-print-schedule'))printSchedule();if(b.id==='save-receipt'){const text=`CAGE Training Academy\nApplication reference: ${access.id}\nPrivate access key: ${access.key}\nReturn to upload payment proof:\n${privateLink()}\n\nKeep this file private. CAGE staff can review your application without this key.`;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.href=url;a.download='CAGE-Application-'+access.id.slice(0,8)+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
document.addEventListener('input',e=>{if(e.target.closest('#application-form')&&current){const form=document.getElementById('application-form'),answers={};for(const f of current.fields)answers[f.id]=f.type==='checkbox'?form.elements[f.id].checked:form.elements[f.id].value;try{sessionStorage.setItem('cage-application-draft:'+current.id,JSON.stringify(answers));}catch{}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['application-form','payment-proof-form','return-form','balance-date-form','correction-form'].includes(f.id))return;e.preventDefault();if(f.dataset.busy)return;f.dataset.busy='true';const b=e.submitter||f.querySelector('button[type=submit],button');if(b)b.disabled=true;try{
 if(f.id==='correction-form'){const form=new FormData(f),answers={};for(const field of correctionFields)answers[field.id]=field.type==='checkbox'?f.elements[field.id].checked:f.elements[field.id].value;form.set('answers',JSON.stringify(answers));form.set('application',access.id);form.set('request_id',f.dataset.request);await request('correct',form,access.key);await statusView();}
 if(f.id==='balance-date-form'){const v=new FormData(f);v.set('application',access.id);await request('payment-plan',v,access.key);await statusView();}
 if(f.id==='return-form'){const v=new FormData(f);access={id:String(v.get('reference')).trim(),key:String(v.get('key')).trim()};await statusView();}
 if(f.id==='application-form'){
 const answers={};for(const field of current.fields)answers[field.id]=field.type==='checkbox'?f.elements[field.id].checked:f.elements[field.id].value;
 const storage='cage-application-pending:'+current.id;if(!pending||pending.intake!==current.id){try{pending=JSON.parse(sessionStorage.getItem(storage)||'null');}catch{}if(!pending||pending.intake!==current.id){pending={intake:current.id,key:Array.from(crypto.getRandomValues(new Uint8Array(32))).map(n=>n.toString(16).padStart(2,'0')).join(''),request:uuid()};}try{sessionStorage.setItem(storage,JSON.stringify(pending));}catch{}}
 const form=new FormData(f);form.set('answers',JSON.stringify(answers));form.set('intake',current.id);form.set('revision',current.revision);form.set('request_id',pending.request);const saved=await request('apply',form,pending.key);access={id:saved.id,key:pending.key};history.replaceState(null,'',privateLink());try{sessionStorage.removeItem('cage-application-draft:'+current.id);}catch{}await statusView();
 }
 if(f.id==='payment-proof-form'){const form=new FormData(f);form.set('application',access.id);if(!paymentId)paymentId=uuid();form.set('upload_id',paymentId);await request('payment',form,access.key);paymentId=null;await statusView();}
 }catch(err){error(err);}finally{delete f.dataset.busy;if(b)b.disabled=false;}});
(async()=>{try{if(!config.supabaseUrl)throw new Error('Applications will open after the CAGE connection is configured.');const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('application')&&hash.has('key')){access={id:hash.get('application'),key:hash.get('key')};await statusView();return;}const loaded=await request('catalog');catalog=Array.isArray(loaded.intakes)?loaded.intakes:[];const id=new URLSearchParams(location.search).get('call');if(id&&catalog.some(c=>c.id===id))showCall(id);else catalogView();}catch(e){root.innerHTML=`<section class="academy-card cage-academy-narrow cage-academy-load-failed"><h1>Courses could not be loaded</h1><p id="cage-academy-error" class="cage-academy-error" role="alert">${esc(e.message||e)}</p><p>Check your connection, then try again. Your browser does not need an account to view published courses.</p><button type="button" id="ad-retry-catalog">Try again</button></section>`;document.getElementById('ad-retry-catalog')?.addEventListener('click',()=>location.reload());}})();
})();
